tables.ddl:
CREATE TABLE vehicle_type_dict (
    type_code VARCHAR(20) PRIMARY KEY COMMENT '类型代码',
    type_name VARCHAR(50) NOT NULL COMMENT '类型名称（客车/货车/危化品车等）',
    category VARCHAR(20) COMMENT '大类'
) ENGINE=InnoDB COMMENT='车辆类型字典';

CREATE TABLE vessel_type_dict (
    type_code SMALLINT PRIMARY KEY COMMENT 'AIS船舶类型代码',
    type_name VARCHAR(50) NOT NULL COMMENT '类型名称',
    category VARCHAR(20) COMMENT '大类'
) ENGINE=InnoDB COMMENT='船舶类型字典';

CREATE TABLE employee_type_dict (
    type_code VARCHAR(20) PRIMARY KEY COMMENT '人员类型代码',
    type_name VARCHAR(50) NOT NULL COMMENT '类型名称（船长/大副/轮机长/水手等）'
) ENGINE=InnoDB COMMENT='人员类型字典';

CREATE TABLE license_type_dict (
    license_code VARCHAR(5) PRIMARY KEY COMMENT '驾照代码',
    license_name VARCHAR(50) NOT NULL COMMENT '驾照名称'
) ENGINE=InnoDB COMMENT='驾照类型字典';

CREATE TABLE energy_type_dict (
    type_code VARCHAR(10) PRIMARY KEY COMMENT '能源类型代码',
    type_name VARCHAR(30) NOT NULL COMMENT '类型名称',
    category VARCHAR(20) COMMENT '大类',
    is_renewable TINYINT(1) DEFAULT 0 COMMENT '是否可再生'
) ENGINE=InnoDB COMMENT='能源类型字典';

CREATE TABLE voltage_level_dict (
    level_code VARCHAR(10) PRIMARY KEY COMMENT '电压等级代码',
    level_name VARCHAR(20) NOT NULL COMMENT '等级名称',
    level_value INT COMMENT '电压值(kV)',
    category VARCHAR(20) COMMENT '类别'
) ENGINE=InnoDB COMMENT='电压等级字典';

CREATE TABLE energy_position_dict (
    position_code VARCHAR(20) PRIMARY KEY COMMENT '岗位代码',
    position_name VARCHAR(50) NOT NULL COMMENT '岗位名称',
    category VARCHAR(30) COMMENT '类别'
) ENGINE=InnoDB COMMENT='能源行业岗位字典';

CREATE TABLE station_type_dict (
    type_code VARCHAR(10) PRIMARY KEY COMMENT '场站类型代码',
    type_name VARCHAR(50) NOT NULL COMMENT '类型名称',
    category VARCHAR(30) COMMENT '大类'
) ENGINE=InnoDB COMMENT='场站类型字典';

CREATE TABLE cert_type_dict (
    cert_type_code VARCHAR(20) PRIMARY KEY COMMENT '资质类型代码',
    cert_type_name VARCHAR(50) NOT NULL COMMENT '资质类型名称',
    category VARCHAR(20) COMMENT '类别',
    valid_years TINYINT COMMENT '有效期(年)'
) ENGINE=InnoDB COMMENT='资质类型字典';

CREATE TABLE customer_status_dict (
  status_code VARCHAR(32) NOT NULL COMMENT '用户状态编码',
  status_name VARCHAR(64) NOT NULL COMMENT '用户状态名称',
  description VARCHAR(255) DEFAULT NULL COMMENT '说明',
  PRIMARY KEY (status_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户状态字典';

CREATE TABLE product_status_dict (
  status_code VARCHAR(32) NOT NULL COMMENT '商品状态编码',
  status_name VARCHAR(64) NOT NULL COMMENT '商品状态名称',
  description VARCHAR(255) DEFAULT NULL COMMENT '说明',
  PRIMARY KEY (status_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商品状态字典';

CREATE TABLE order_status_dict (
  status_code VARCHAR(32) NOT NULL COMMENT '订单状态编码',
  status_name VARCHAR(64) NOT NULL COMMENT '订单状态名称',
  description VARCHAR(255) DEFAULT NULL COMMENT '说明',
  PRIMARY KEY (status_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='订单状态字典';

CREATE TABLE payment_method_dict (
  method_code VARCHAR(32) NOT NULL COMMENT '支付方式编码',
  method_name VARCHAR(64) NOT NULL COMMENT '支付方式名称',
  description VARCHAR(255) DEFAULT NULL COMMENT '说明',
  PRIMARY KEY (method_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='支付方式字典';

CREATE TABLE payment_status_dict (
  status_code VARCHAR(32) NOT NULL COMMENT '支付状态编码',
  status_name VARCHAR(64) NOT NULL COMMENT '支付状态名称',
  description VARCHAR(255) DEFAULT NULL COMMENT '说明',
  PRIMARY KEY (status_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='支付状态字典';

CREATE TABLE refund_reason_dict (
  reason_code VARCHAR(32) NOT NULL COMMENT '退款原因编码',
  reason_name VARCHAR(64) NOT NULL COMMENT '退款原因名称',
  description VARCHAR(255) DEFAULT NULL COMMENT '说明',
  PRIMARY KEY (reason_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='退款原因字典';

CREATE TABLE order_channel_dict (
  channel_code VARCHAR(32) NOT NULL COMMENT '下单渠道编码',
  channel_name VARCHAR(64) NOT NULL COMMENT '下单渠道名称',
  description VARCHAR(255) DEFAULT NULL COMMENT '说明',
  PRIMARY KEY (channel_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='下单渠道字典';

CREATE TABLE platform_dict (
  platform_code VARCHAR(32) NOT NULL COMMENT '销售平台编码',
  platform_name VARCHAR(64) NOT NULL COMMENT '销售平台名称',
  description VARCHAR(255) DEFAULT NULL COMMENT '说明',
  PRIMARY KEY (platform_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='销售平台字典';

